  str_season_mission_desc_8001011 = "หลังจากที่อีฟทำงานหนักเสร็จสิ้น เธอรู้สึกกระหายน้ำจึงเดินไปยังบ่อเพื่อดื่มน้ำ แต่เธอสังเกตเห็นสิ่งแปลกปลอมรอบ ๆ บริเวณนั้น",
  str_season_mission_desc_8001012 = "หลังจากที่อีฟทำงานหนักเสร็จสิ้น เธอรู้สึกกระหายน้ำจึงเดินไปยังบ่อเพื่อดื่มน้ำ แต่เธอสังเกตเห็นสิ่งแปลกปลอมรอบ ๆ บริเวณนั้น",
  str_season_mission_desc_8001013 = "อีฟยกหัวขึ้น หายใจพร้อมคำสาปแช่งสภาพอากาศในวันนั้น แต่ก็พบสิ่งใหม่ๆ ที่ใกล้ๆ...",
  str_season_mission_desc_8001014 = "อีฟยกหัวขึ้น หายใจพร้อมคำสาปแช่งสภาพอากาศในวันนั้น แต่ก็พบสิ่งใหม่ๆ ที่ใกล้ๆ...",
  str_season_mission_desc_8001015 = "อีฟพยายามเขย่าหัวให้ห่างจากสุนัขตัวใหญ่ที่มีขนสีแดง แต่เมื่อเธอถึงทางเข้าของถนนเทลสตรีท เธอได้ยินเสียงกรีดร้องเร่งด่วนจากคนๆ หนึ่งรอบข้าง...",
  str_season_mission_desc_8001016 = "อีฟพยายามเขย่าหัวให้ห่างจากสุนัขตัวใหญ่ที่มีขนสีแดง แต่เมื่อเธอถึงทางเข้าของถนนเทลสตรีท เธอได้ยินเสียงกรีดร้องเร่งด่วนจากคนๆ หนึ่งรอบข้าง...",
  str_season_mission_desc_8001017 = "ในขณะนั้น Eve ไม่มีตัวเลือกอื่นนอกจากต้องติดตามรอยเท้าของ \"Eve\" คนอื่น ๆ และผจญภัยหยั่งลึกลงไปในถนนเทลสตรีท",
  str_season_mission_desc_8001018 = "ในขณะนั้น Eve ไม่มีตัวเลือกอื่นนอกจากต้องติดตามรอยเท้าของ \"Eve\" คนอื่น ๆ และผจญภัยหยั่งลึกลงไปในถนนเทลสตรีท",
  str_season_mission_desc_8001019 = "ทำไมในโลกนี้จะมี \"ฉัน\" คนอื่นอีกคนหนึ่ง? ใจของอีฟยุ่งเหยิง สับสนและวุ่นวาย",
  str_season_mission_desc_8001020 = "ทำไมในโลกนี้จะมี \"ฉัน\" คนอื่นอีกคนหนึ่ง? ใจของอีฟยุ่งเหยิง สับสนและวุ่นวาย",
  str_season_mission_desc_8001021 = "ในความลึกของถนนเทลสตรีท มีห้องหนึ่งที่อีฟไม่เคยพบมาก่อน และภายในห้องนั้น ดูเหมือนว่าจะมีเด็กผู้หญิงถูกกักตัวอยู่...?",
  str_season_mission_desc_8001022 = "ในความลึกของถนนเทลสตรีท มีห้องหนึ่งที่อีฟไม่เคยพบมาก่อน และภายในห้องนั้น ดูเหมือนว่าจะมีเด็กผู้หญิงถูกกักตัวอยู่...?",
  str_season_mission_desc_8001023 = "อีฟไม่เคยคิดถึงเรื่องการออกจากบ้านเล็ก ๆ ที่สงบสุขของเธอ แต่ตอนนี้เธอพบว่าตัวเองต้องเผชิญกับการตัดสินใจที่เธอไม่สามารถหลีกเลี่ยงได้",
  str_season_mission_desc_8001024 = "อีฟไม่เคยคิดถึงเรื่องการออกจากบ้านเล็ก ๆ ที่สงบสุขของเธอ แต่ตอนนี้เธอพบว่าตัวเองต้องเผชิญกับการตัดสินใจที่เธอไม่สามารถหลีกเลี่ยงได้",
  str_season_mission_desc_8001025 = "ขณะที่เธอเดินต่อไป อีฟสูญหายติดตามระยะทางที่เธอเดินมา และอากาศกลับร้อนและแห้งยิ่งขึ้น มากกว่าทะเลทรายเรดีเซลที่ร้อนแรง...",
  str_season_mission_desc_8001026 = "ขณะที่เธอเดินต่อไป อีฟสูญหายติดตามระยะทางที่เธอเดินมา และอากาศกลับร้อนและแห้งยิ่งขึ้น มากกว่าทะเลทรายเรดีเซลที่ร้อนแรง...",
  str_season_mission_desc_8001027 = "เส้นทางที่ \"อีฟ\" ชี้ให้เห็นไม่เพียงแค่หนักแน่น แต่ยังถูกปีศาจอิคลิพไซท์หลอกหลอนอีกด้วย อีฟลังลั้น ไม่แน่ใจว่าควรจะเดินหน้าต่อหรือไม่",
  str_season_mission_desc_8001028 = "เส้นทางที่ \"อีฟ\" ชี้ให้เห็นไม่เพียงแค่หนักแน่น แต่ยังถูกปีศาจอิคลิพไซท์หลอกหลอนอีกด้วย อีฟลังลั้น ไม่แน่ใจว่าควรจะเดินหน้าต่อหรือไม่",
  str_season_mission_desc_8001029 = "พร้อมกับการตัดสินใจแล้ว อีฟเดินหน้าต่อไปด้วยความมั่นใจและยกหัวสูง!",
  str_season_mission_desc_8001030 = "พร้อมกับการตัดสินใจแล้ว อีฟเดินหน้าต่อไปด้วยความมั่นใจและยกหัวสูง!",
  str_season_mission_desc_8001031 = "ระวังลาวาที่ร้อนแสบที่กำลังพลิกตัวอยู่ข้างเท้าคุณในที่ตักน้ำ อย่าตกลงไปนะ!",
  str_season_mission_desc_8001032 = "ระวังลาวาที่ร้อนแสบที่กำลังพลิกตัวอยู่ข้างเท้าคุณในที่ตักน้ำ อย่าตกลงไปนะ!",
  str_season_mission_desc_8001033 = "อีฟเห็น \"อีฟ\" ในที่ห่างไกล... คำตอบอัลติเมทอาจรออยู่ที่นั่นเหรอ?",
  str_season_mission_desc_8001034 = "อีฟเห็น \"อีฟ\" ในที่ห่างไกล... คำตอบอัลติเมทอาจรออยู่ที่นั่นเหรอ?",
  str_season_mission_desc_8001035 = "ในที่สุด... ในที่สุดก็ไปถึงที่ที่ \"อีฟ\" อยู่ คำตอบแบบไหนที่รอคอยกันนะ?",
  str_season_mission_desc_8001036 = "ในที่สุด... ในที่สุดก็ไปถึงที่ที่ \"อีฟ\" อยู่ คำตอบแบบไหนที่รอคอยกันนะ?",
